// Grouping dataset using ES2024 Object.groupBy:
const students = [
  { name: 'Swadeep', course: 'JS', score: 95 },
  { name: 'Tuhina', course: 'JS', score: 88 },
  { name: 'Debangshu', course: 'Python', score: 92 }
];
const grouped = Object.groupBy(students, s => s.course);

